data:
{
 "parameters": [
  {
   "$ref": "#/components/parameters/organizationId"
  }
 ],
 "get": {
  "operationId": "getSpendBudget",
  "tags": [
   "Catalog"
  ],
  "summary": "Read the organization's spend budget",
  "description": "The ceiling on what this organization may spend on MCPJam-billed work \u2014 chat, evals, judges and computer time \u2014 in the current billing window, and how much of it has been spent.\n\nAny member may read it: a member who cannot raise the ceiling still needs to know it exists, because it is what refused their run. `capUsd: null` means the organization is uncapped, which is the default.\n\nRuns that use your own provider keys are never counted against the budget and never blocked by it. Neither is the free daily allowance \u2014 it is not credits.",
  "responses": {
   "200": {
    "description": "The organization's spend budget.",
    "content": {
     "application/json": {
      "schema": {
       "$ref": "#/components/schemas/SpendBudget"
      }
     }
    }
   },
   "401": {
    "$ref": "#/components/responses/Unauthorized"
   },
   "403": {
    "$ref": "#/components/responses/Forbidden"
   },
   "404": {
    "$ref": "#/components/responses/NotFound"
   },
   "429": {
    "$ref": "#/components/responses/RateLimited"
   },
   "500": {
    "$ref": "#/components/responses/InternalError"
   }
  }
 },
 "put": {
  "operationId": "setSpendBudget",
  "tags": [
   "Catalog"
  ],
  "summary": "Set the organization's spend budget",
  "description": "Set or replace the ceiling. **Requires organization owner or admin.**\n\nWhen the budget is reached, new MCPJam-billed work \u2014 chat turns, eval runs, computer starts \u2014 is refused for the whole organization until the window resets or an owner or admin raises the cap. Work already in flight finishes, and running computers keep going until they hibernate.\n\n`capUsd` is stored as whole credits (1 credit = 1 cent), so it is rounded to the cent; the response reports what was kept. Changing the cap mid-window does not reset the spend counter, and does not re-announce a threshold the organization was already told about.",
  "requestBody": {
   "required": true,
   "content": {
    "application/json": {
     "schema": {
      "$ref": "#/components/schemas/SpendBudgetInput"
     }
    }
   }
  },
  "responses": {
   "200": {
    "description": "The stored spend budget.",
    "content": {
     "application/json": {
      "schema": {
       "$ref": "#/components/schemas/SpendBudget"
      }
     }
    }
   },
   "401": {
    "$ref": "#/components/responses/Unauthorized"
   },
   "403": {
    "$ref": "#/components/responses/Forbidden"
   },
   "404": {
    "$ref": "#/components/responses/NotFound"
   },
   "429": {
    "$ref": "#/components/responses/RateLimited"
   },
   "500": {
    "$ref": "#/components/responses/InternalError"
   }
  }
 },
 "delete": {
  "operationId": "clearSpendBudget",
  "tags": [
   "Catalog"
  ],
  "summary": "Remove the organization's spend budget",
  "description": "Leave the organization uncapped. **Requires organization owner or admin.**\n\nThe window's spend counter survives: it is a record of spend, not of the budget, and a budget set again later measures against the spend already made this period.",
  "responses": {
   "200": {
    "description": "The spend budget, now uncapped.",
    "content": {
     "application/json": {
      "schema": {
       "$ref": "#/components/schemas/SpendBudget"
      }
     }
    }
   },
   "401": {
    "$ref": "#/components/responses/Unauthorized"
   },
   "403": {
    "$ref": "#/components/responses/Forbidden"
   },
   "404": {
    "$ref": "#/components/responses/NotFound"
   },
   "429": {
    "$ref": "#/components/responses/RateLimited"
   },
   "500": {
    "$ref": "#/components/responses/InternalError"
   }
  }
 }
}
